namespace cf {
static void checker(QPainter &p,QRect r){p.fillRect(r,QColor("#929da6"));for(int y=r.top();y<r.bottom();y+=12)for(int x=r.left();x<r.right();x+=12)if(((x-r.x())/12+(y-r.y())/12)%2)p.fillRect(QRect(x,y,12,12).intersected(r),QColor("#bac1c6"));}
SheetCanvas::SheetCanvas(QWidget *p):QWidget(p){setMinimumSize(400,260);setSizePolicy(QSizePolicy::Expanding,QSizePolicy::Expanding);}
QRect SheetCanvas::sheetRect()const{if(asset.width<=0||asset.height<=0)return {};QSize size(asset.width,asset.height);if(zoom>0)size=QSize(qRound(asset.width*zoom),qRound(asset.height*zoom));else size.scale(width()-24,height()-24,Qt::KeepAspectRatio);return QRect(QPoint((width()-size.width())/2,(height()-size.height())/2),size);}
void SheetCanvas::refreshSize(){setMinimumSize(zoom>0?QSize(qMax(1,qRound(asset.width*zoom)+24),qMax(1,qRound(asset.height*zoom)+24)):QSize(400,260));updateGeometry();update();}
void SheetCanvas::setZoom(double v){zoom=v==0?0:qBound(.25,v,32.0);refreshSize();if(onZoom)onZoom(zoom);}
void SheetCanvas::wheelEvent(QWheelEvent *e){if(e->modifiers()&(Qt::ControlModifier|Qt::MetaModifier)){double base=zoom>0?zoom:double(sheetRect().width())/qMax(1,asset.width);setZoom(base*(e->angleDelta().y()>0?1.25:.8));e->accept();}else QWidget::wheelEvent(e);}
QWidget *sheetViewer(SheetCanvas *sheet,QWidget *parent){auto *widget=new QWidget(parent);auto *layout=new QVBoxLayout(widget);layout->setContentsMargins(0,0,0,0);auto *bar=new QHBoxLayout;auto *minus=new QPushButton("−"),*plus=new QPushButton("+"),*fit=new QPushButton("Fit");auto *percent=new QComboBox;for(auto entry:{qMakePair(QString("Fit"),0.),qMakePair(QString("25%"),.25),qMakePair(QString("50%"),.5),qMakePair(QString("100%"),1.),qMakePair(QString("200%"),2.),qMakePair(QString("400%"),4.),qMakePair(QString("800%"),8.),qMakePair(QString("1600%"),16.),qMakePair(QString("3200%"),32.)})percent->addItem(entry.first,entry.second);bar->addWidget(new QLabel("Zoom"));bar->addWidget(minus);bar->addWidget(percent);bar->addWidget(plus);bar->addWidget(fit);bar->addStretch();bar->addWidget(new QLabel("Ctrl/Cmd + wheel · scrollbars to pan"));layout->addLayout(bar);auto *scroll=new QScrollArea;scroll->setWidgetResizable(true);scroll->setWidget(sheet);layout->addWidget(scroll,1);QObject::connect(percent,&QComboBox::activated,widget,[sheet,percent](int i){sheet->setZoom(percent->itemData(i).toDouble());});QObject::connect(minus,&QPushButton::clicked,widget,[sheet]{sheet->setZoom((sheet->zoom?sheet->zoom:1.)*.8);});QObject::connect(plus,&QPushButton::clicked,widget,[sheet]{sheet->setZoom((sheet->zoom?sheet->zoom:1.)*1.25);});QObject::connect(fit,&QPushButton::clicked,widget,[sheet]{sheet->setZoom(0);});sheet->onZoom=[percent](double z){QSignalBlocker block(percent);int i=percent->findData(z);if(i>=0)percent->setCurrentIndex(i);else{if(percent->count()>9)percent->removeItem(9);percent->addItem(QString::number(qRound(z*100))+"%",z);percent->setCurrentIndex(percent->count()-1);}};return widget;}
void SheetCanvas::paintEvent(QPaintEvent *){QPainter p(this);p.fillRect(rect(),QColor("#111923"));auto image=sheetImage;if(image.isNull())return;auto target=sheetRect();checker(p,target);p.drawImage(target,image);
    for(int i=0;i<asset.frameCount();++i){QRectF cell(target.x()+i%asset.columns*double(target.width())/asset.columns,target.y()+i/asset.columns*double(target.height())/asset.rows,double(target.width())/asset.columns,double(target.height())/asset.rows);
        if(i>=first&&i<=last)p.fillRect(cell,QColor(244,158,90,45));p.setPen(QPen(i==current?QColor("#fff0bc"):QColor("#ee9869"),i==current?3:1));p.drawRect(cell.adjusted(1,1,-1,-1));p.setPen(Qt::white);p.drawText(cell.adjusted(5,4,-3,-3),Qt::AlignTop|Qt::AlignLeft,QString::number(i));}
}
void SheetCanvas::mousePressEvent(QMouseEvent *e){auto r=sheetRect();if(!r.contains(e->pos())||asset.columns<1||asset.rows<1)return;int x=qMin(asset.columns-1,(e->pos().x()-r.x())*asset.columns/r.width()),y=qMin(asset.rows-1,(e->pos().y()-r.y())*asset.rows/r.height());if(onFrame)onFrame(y*asset.columns+x,e->modifiers()&Qt::ShiftModifier);}
AnimationPreview::AnimationPreview(QWidget *p):QWidget(p){setMinimumSize(240,240);auto *timer=new QTimer(this);timer->setTimerType(Qt::PreciseTimer);auto *elapsed=new QElapsedTimer;elapsed->start();connect(this,&QObject::destroyed,[elapsed]{delete elapsed;});auto debt=std::make_shared<double>(0);auto previous=std::make_shared<qint64>(0);connect(timer,&QTimer::timeout,this,[this,elapsed,debt,previous]{qint64 now=elapsed->nsecsElapsed();double dt=(now-*previous)/1e6;*previous=now;if(!isVisible()||!state.playing){*debt=0;return;}*debt+=dt;auto data=asset.clips();if(clip<0||clip>=data.size())return;while(*debt>=1000.0/60){cf_animation_tick(&state,&data[clip]);*debt-=1000.0/60;}if(onStatus)onStatus(QString("Frame %1 / %2 · %3").arg(state.frame).arg(asset.frameCount()-1).arg(state.finished?"finished (holding final frame)":data[clip].loop?"looping":"playing once"));update();});timer->start(4);}
void AnimationPreview::play(){auto data=asset.clips();if(clip<0||clip>=data.size())return;cf_animation_play(&state,&data[clip]);update();}
void AnimationPreview::stop(){state.playing=0;update();}
void AnimationPreview::paintEvent(QPaintEvent *){QPainter p(this);checker(p,rect());auto source=asset.frameRect(state.frame);auto image=sheetImage.copy(source);auto clips=asset.clips();if(clip>=0&&clip<clips.size())image=image.mirrored(clips[clip].flags&2,clips[clip].flags&4);if(image.isNull())return;int scale=qMax(1,qMin((width()-24)/image.width(),(height()-24)/image.height()));QSize size=image.size()*scale;p.drawImage(QRect(QPoint((width()-size.width())/2,(height()-size.height())/2),size),image);}
AnimationEditor::AnimationEditor(QWidget *parent):QWidget(parent){
    auto *root=new QHBoxLayout(this);auto *left=new QVBoxLayout;left->addWidget(new QLabel("SPRITE SHEETS"));sprites=new QListWidget;left->addWidget(sprites,1);auto *import=new QPushButton("Import sprite sheet…");left->addWidget(import);left->addWidget(new QLabel("ANIMATIONS"));clips=new QListWidget;left->addWidget(clips,1);auto *duplicate=new QPushButton("Duplicate clip (shared frames)");left->addWidget(duplicate);connect(duplicate,&QPushButton::clicked,this,[this]{mutate([&](RasterAsset &a){if(a.animations.isEmpty()||a.animations.size()>=32)return;auto clip=a.animations[qBound(0,selectedClip,int(a.animations.size())-1)];int suffix=2;QString base=clip.name.left(26);do{clip.name=base+"_"+QString::number(suffix++);}while(a.animationIndex(clip.name)>=0);a.animations<<clip;selectedClip=a.animations.size()-1;});});auto *add=new QPushButton("+ Animation"),*remove=new QPushButton("Delete animation");left->addWidget(add);left->addWidget(remove);auto *side=new QWidget;side->setLayout(left);side->setMaximumWidth(250);root->addWidget(side);
    auto *center=new QVBoxLayout;auto *grid=new QHBoxLayout;columns=new QSpinBox;rows=new QSpinBox;columns->setRange(1,8);rows->setRange(1,8);grid->addWidget(new QLabel("Sheet width (frames)"));grid->addWidget(columns);grid->addWidget(new QLabel("Sheet height (frames)"));grid->addWidget(rows);center->addLayout(grid);info=new QLabel;info->setWordWrap(true);center->addWidget(info);sheet=new SheetCanvas;center->addWidget(sheetViewer(sheet),1);center->addWidget(new QLabel("Frames read left to right, then top to bottom. Click sets the start; Shift-click sets the end."));root->addLayout(center,1);
    auto *right=new QVBoxLayout;auto *form=new QFormLayout;name=new QLineEdit;first=new QSpinBox;last=new QSpinBox;duration=new QDoubleSpinBox;duration->setRange(.017,60);duration->setDecimals(3);duration->setSingleStep(.1);duration->setSuffix(" s");loop=new QCheckBox("Loop animation");form->addRow("Animation name",name);form->addRow("First frame (inclusive)",first);form->addRow("Last frame (inclusive)",last);form->addRow("Total animation duration",duration);reverse=new QCheckBox("Reverse playback");flipH=new QCheckBox("Mirror horizontally");flipV=new QCheckBox("Mirror vertically");form->addRow(loop);form->addRow(reverse);form->addRow(flipH);form->addRow(flipV);right->addLayout(form);preview=new AnimationPreview;right->addWidget(preview);playStatus=new QLabel;playStatus->setWordWrap(true);right->addWidget(playStatus);auto *play=new QPushButton("Play / Fire"),*stop=new QPushButton("Stop");right->addWidget(play);right->addWidget(stop);auto *help=new QLabel("Duration covers the complete frame range.\nOnce: hold the last frame after finishing.\nLoop: repeat until stopped or replaced.\n\nBind named animations in a character script:\nanimation idle\non_move walk\non_idle idle\non_interact attack\n\nAn action fires when Interact is pressed.\nOne-shot actions return to idle/move.\nLooping actions stop when movement starts.");help->setWordWrap(true);right->addWidget(help);right->addStretch();auto *properties=new QWidget;properties->setLayout(right);properties->setMaximumWidth(340);root->addWidget(properties);
    connect(sprites,&QListWidget::currentRowChanged,this,[this](int){if(!filling)selectAsset();});connect(clips,&QListWidget::currentRowChanged,this,[this](int i){if(!filling){selectedClip=i;fill();}});
    connect(import,&QPushButton::clicked,this,[this]{if(project.assets.size()>=32)return;RasterAsset a;if(!importAsset(this,"sprite",a))return;auto p=project;p.assets<<a;assetId=a.id;selectedClip=0;if(onEdit)onEdit(p);});
    connect(add,&QPushButton::clicked,this,[this]{mutate([&](RasterAsset &a){if(a.animations.size()>=32)return;QString n="animation";int i=1;while(a.animationIndex(n)>=0)n="animation_"+QString::number(i++);a.animations.append({n,0,a.frameCount()-1,qMax(6,a.frameCount()*6),true});selectedClip=a.animations.size()-1;});});
    connect(remove,&QPushButton::clicked,this,[this]{mutate([&](RasterAsset &a){if(selectedClip>=0&&selectedClip<a.animations.size())a.animations.removeAt(selectedClip);selectedClip=0;});});
    auto layout=[this]{mutate([&](RasterAsset &a){a.columns=columns->value();a.rows=rows->value();for(auto &clip:a.animations){clip.first=qMin(clip.first,a.frameCount()-1);clip.last=qBound(clip.first,clip.last,a.frameCount()-1);clip.duration=qMax(clip.duration,clip.last-clip.first+1);}});};connect(columns,&QSpinBox::valueChanged,this,layout);connect(rows,&QSpinBox::valueChanged,this,layout);
    auto edit=[this]{mutate([&](RasterAsset &a){if(selectedClip<0||selectedClip>=a.animations.size())return;auto &clip=a.animations[selectedClip];clip.name=name->text();clip.first=first->value();clip.last=qMax(clip.first,last->value());clip.duration=qMax(clip.last-clip.first+1,qRound(duration->value()*60));clip.loop=loop->isChecked();clip.reverse=reverse->isChecked();clip.flipH=flipH->isChecked();clip.flipV=flipV->isChecked();});};
    connect(name,&QLineEdit::editingFinished,this,edit);connect(first,&QSpinBox::valueChanged,this,edit);connect(last,&QSpinBox::valueChanged,this,edit);connect(duration,&QDoubleSpinBox::valueChanged,this,edit);connect(loop,&QCheckBox::toggled,this,edit);for(auto *box:{reverse,flipH,flipV})connect(box,&QCheckBox::toggled,this,edit);
    connect(play,&QPushButton::clicked,preview,[this]{preview->play();});connect(stop,&QPushButton::clicked,preview,[this]{preview->stop();playStatus->setText(QString("Stopped at frame %1").arg(preview->state.frame));});preview->onStatus=[this](QString s){playStatus->setText(s);sheet->current=preview->state.frame;sheet->update();};
    sheet->onFrame=[this](int frame,bool end){mutate([&](RasterAsset &a){if(selectedClip<0||selectedClip>=a.animations.size())return;auto &clip=a.animations[selectedClip];if(end){clip.last=qMax(clip.first,frame);}else{clip.first=frame;clip.last=qMax(frame,clip.last);}clip.duration=qMax(clip.duration,clip.last-clip.first+1);});};
}
int AnimationEditor::assetIndex()const{for(int i=0;i<project.assets.size();++i)if(project.assets[i].id==assetId)return i;return -1;}
void AnimationEditor::setProject(const Project &p){filling=true;project=p;sprites->clear();for(auto &a:p.assets)if(a.kind=="sprite"){auto *item=new QListWidgetItem(a.name);item->setData(Qt::UserRole,a.id);sprites->addItem(item);}int row=-1;for(int i=0;i<sprites->count();++i)if(sprites->item(i)->data(Qt::UserRole).toString()==assetId)row=i;if(row<0&&sprites->count())row=0;sprites->setCurrentRow(row);assetId=row>=0?sprites->item(row)->data(Qt::UserRole).toString():QString();filling=false;fill();}
void AnimationEditor::selectAsset(){assetId=sprites->currentItem()?sprites->currentItem()->data(Qt::UserRole).toString():QString();selectedClip=0;fill();}
void AnimationEditor::fill(){filling=true;int i=assetIndex();RasterAsset a;if(i>=0)a=project.assets[i];columns->setValue(a.columns);rows->setValue(a.rows);clips->clear();for(auto &c:a.animations)clips->addItem(c.name);selectedClip=qBound(0,selectedClip,qMax(0,int(a.animations.size())-1));clips->setCurrentRow(a.animations.isEmpty()?-1:selectedClip);
    first->setRange(0,qMax(0,a.frameCount()-1));last->setRange(0,qMax(0,a.frameCount()-1));bool has=i>=0&&selectedClip<a.animations.size();for(QWidget *w:QList<QWidget *>{name,first,last,duration,loop,reverse,flipH,flipV})w->setEnabled(has);
    if(has){auto c=a.animations[selectedClip];name->setText(c.name);first->setValue(c.first);last->setValue(c.last);duration->setValue(c.duration/60.0);loop->setChecked(c.loop);reverse->setChecked(c.reverse);flipH->setChecked(c.flipH);flipV->setChecked(c.flipV);}else name->clear();
    sheet->asset=a;sheet->sheetImage=a.image(project.target=="gb");preview->sheetImage=sheet->sheetImage;sheet->first=has?a.animations[selectedClip].first:0;sheet->last=has?a.animations[selectedClip].last:0;sheet->dmg=project.target=="gb";sheet->refreshSize();preview->asset=a;preview->clip=selectedClip;preview->dmg=project.target=="gb";preview->play();
    RasterAsset checked;QString error;bool valid=i>=0&&RasterAsset::fromJson(a.toJson(),checked,error);info->setText(i<0?"Import a sprite sheet to begin.":valid?QString("%1 × %2 pixels per frame · %3 frames · %4 hardware tiles per frame").arg(a.frameWidth()).arg(a.frameHeight()).arg(a.frameCount()).arg(a.frameTileCount()):"Invalid grid or animation. Frames must be 8–32 px in multiples of 8; ranges and duration must fit.");filling=false;
}
void AnimationEditor::mutate(const std::function<void(RasterAsset &)> &fn){if(filling||assetIndex()<0)return;auto p=project;fn(p.assets[assetIndex()]);RasterAsset checked;QString error;if(!RasterAsset::fromJson(p.assets[assetIndex()].toJson(),checked,error)){info->setText("Not applied: use a grid with 8–32 px frames and unique animation names. Each frame needs at least one tick of duration.");return;}if(onEdit)onEdit(p);}
}
